SELECT (SELECT COUNT(*) FROM publicationinfo WHERE Patents_info LIKE '%6037095%') AS cited_row_exists, (SELECT COUNT(*) FROM publicationinfo WHERE citation LIKE '%7724398%') AS c2, (SELECT COUNT(*) FROM publicationinfo WHERE citation LIKE '%3353000%') AS c3, (SELECT COUNT(*) FROM publicationinfo WHERE citation LIKE '%7052856%') AS c4, (SELECT COUNT(*) FROM publicationinfo WHERE citation LIKE '%1212462%') AS c5, (SELECT COUNT(*) FROM publicationinfo WHERE citation LIKE '%"application_number": "US-%') AS appnum_filled, (SELECT COUNT(*) FROM publicationinfo WHERE citation LIKE '%UNIV%') AS cit_univ
